CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS permissions (user_id INT UNSIGNED NOT NULL, menu VARCHAR(40) NOT NULL, PRIMARY KEY(user_id,menu), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL, child_name VARCHAR(120) NOT NULL, birth_date DATE NULL, address VARCHAR(255) NULL, social_media VARCHAR(120) NULL, child_complaint TEXT NULL, weight_kg DECIMAL(5,2) NULL, height_cm DECIMAL(5,2) NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_customer_phone(phone)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id INT UNSIGNED NOT NULL UNIQUE, member_code VARCHAR(30) NOT NULL UNIQUE, start_date DATE NOT NULL, end_date DATE NULL, status ENUM('aktif','nonaktif') NOT NULL DEFAULT 'aktif', FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS treatments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) NOT NULL DEFAULT '', name VARCHAR(120) NOT NULL, treatment_type VARCHAR(80) NOT NULL DEFAULT 'Umum', duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 60, price DECIMAL(12,2) NOT NULL DEFAULT 0, member_price DECIMAL(12,2) NOT NULL DEFAULT 0, therapist_fee DECIMAL(12,2) NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(24) NOT NULL, name VARCHAR(120) NOT NULL, unit VARCHAR(30) NOT NULL DEFAULT 'pcs', cost_price DECIMAL(12,2) NOT NULL DEFAULT 0, price DECIMAL(12,2) NOT NULL DEFAULT 0, stock INT UNSIGNED NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS visits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, transaction_code VARCHAR(32) NULL, customer_id INT UNSIGNED NOT NULL, treatment_id INT UNSIGNED NULL, product_id INT UNSIGNED NULL, item_type ENUM('treatment','product') NOT NULL DEFAULT 'treatment', quantity INT UNSIGNED NOT NULL DEFAULT 1, shift_id BIGINT UNSIGNED NULL, therapist_id INT UNSIGNED NULL, therapist_fee DECIMAL(12,2) NULL, user_id INT UNSIGNED NOT NULL, visit_date DATETIME NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_method ENUM('Tunai','Transfer','QRIS','Lainnya') NOT NULL DEFAULT 'Tunai', notes VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_visits_date(visit_date), INDEX idx_visits_customer(customer_id,visit_date), INDEX idx_visit_transaction(transaction_code), INDEX idx_visits_shift(shift_id), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(treatment_id) REFERENCES treatments(id) ON DELETE RESTRICT, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_code VARCHAR(16) NULL UNIQUE, customer_id INT UNSIGNED NOT NULL, treatment_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, reserved_at DATETIME NOT NULL, status ENUM('Menunggu','Dikonfirmasi','Selesai','Batal') NOT NULL DEFAULT 'Menunggu', notes VARCHAR(255) NULL, visit_id BIGINT UNSIGNED NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_reservation_time(reserved_at), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT, FOREIGN KEY(treatment_id) REFERENCES treatments(id) ON DELETE RESTRICT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS reservation_day_locks (service_date DATE PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS app_settings (setting_key VARCHAR(64) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS stock_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, movement_type ENUM('masuk','keluar','penyesuaian') NOT NULL, quantity INT NOT NULL, stock_after INT NOT NULL, unit_cost DECIMAL(12,2) NULL, reference VARCHAR(40) NULL, notes VARCHAR(255) NULL, user_id INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, INDEX idx_stock_product(product_id,created_at), INDEX idx_stock_date(created_at), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS shifts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, status ENUM('buka','tutup') NOT NULL DEFAULT 'buka', opened_by INT UNSIGNED NOT NULL, opened_at DATETIME NOT NULL, opening_cash DECIMAL(12,2) NOT NULL DEFAULT 0, open_notes VARCHAR(255) NULL, closed_by INT UNSIGNED NULL, closed_at DATETIME NULL, cash_sales DECIMAL(12,2) NULL, noncash_sales DECIMAL(12,2) NULL, cash_expenses DECIMAL(12,2) NULL, expected_cash DECIMAL(12,2) NULL, counted_cash DECIMAL(12,2) NULL, difference DECIMAL(12,2) NULL, close_notes VARCHAR(255) NULL, INDEX idx_shift_status(status), FOREIGN KEY(opened_by) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(closed_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS subscriptions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, start_date DATE NOT NULL, end_date DATE NOT NULL, days INT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL DEFAULT 0, payment_method VARCHAR(30) NULL, notes VARCHAR(255) NULL, user_id INT UNSIGNED NULL, created_at DATETIME NOT NULL, INDEX idx_sub_end(end_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, shift_id BIGINT UNSIGNED NULL, expense_date DATETIME NOT NULL, category VARCHAR(60) NOT NULL, description VARCHAR(255) NULL, amount DECIMAL(12,2) NOT NULL, source ENUM('Kas','Non-kas') NOT NULL DEFAULT 'Kas', user_id INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, INDEX idx_exp_shift(shift_id), INDEX idx_exp_date(expense_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;